#!/usr/bin/env bash
# Runs in the work dir after the last turn; prints one JSON object of named
# booleans. Generated by bench/search_fixtures.py: the expected answer was
# computed from the tracked files of the fixture, not written by hand.
exec "${BENCH_PYTHON:-python3}" - <<'PY'
import json, os, re, subprocess, sys
from pathlib import Path

EXPECTED = json.loads('{"callers": ["pkg/billing/invoice_run.py", "pkg/notify/dunning.py", "pkg/orders/checkout.py", "pkg/orders/retry.py", "pkg/reports/revenue.py", "pkg/sync/replay.py", "scripts/backfill.py", "web/client/pay.js"]}')
p = Path("callers.txt")
got = sorted({l.strip().strip("`") for l in p.read_text().splitlines() if l.strip()}) if p.exists() else []
want = EXPECTED["callers"]
hit = len(set(got) & set(want))
Path(os.environ["BENCH_REPORT"]).write_text(json.dumps({"found": hit, "wanted": len(want), "extra": sorted(set(got) - set(want)), "missing": sorted(set(want) - set(got))}))
print(json.dumps({"answered": bool(got), "complete": hit == len(want), "no_extras": not (set(got) - set(want))}))
PY
